-- Lets people log in with email OR employee code; adds the 4 staff who have no email.

-- 1) schema: email becomes optional, add the emp_code column + unique index
ALTER TABLE users ALTER COLUMN email DROP NOT NULL;
ALTER TABLE users ADD COLUMN IF NOT EXISTS emp_code VARCHAR(40);
CREATE UNIQUE INDEX IF NOT EXISTS ix_users_emp_code ON users (emp_code);

